describe('Search Results Sorting', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should sort search results by relevance, price, and date', () => {
    // Setup: Perform a search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Verify relevance sort button is visible
    cy.get('[data-testid="sort-relevance-btn"]').should('be.visible');

    // Click relevance sort button
    cy.get('[data-testid="sort-relevance-btn"]').click();

    // Verify results are now sorted by relevance
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'Laptop');
    cy.get('[data-testid="search-result-item"]').last().should('contain', 'Laptop');

    // Verify price sort button is visible
    cy.get('[data-testid="sort-price-btn"]').should('be.visible');

    // Click price sort button
    cy.get('[data-testid="sort-price-btn"]').click();

    // Verify results are now sorted by price
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'Laptop');
    cy.get('[data-testid="search-result-item"]').last().should('contain', 'Laptop');

    // Verify date sort button is visible
    cy.get('[data-testid="sort-date-btn"]').should('be.visible');

    // Click date sort button
    cy.get('[data-testid="sort-date-btn"]').click();

    // Verify results are now sorted by date
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'Laptop');
    cy.get('[data-testid="search-result-item"]').last().should('contain', 'Laptop');
  });

  it('should handle edge case when no results are found', () => {
    // Setup: Perform a search for an unavailable product
    cy.get('[data-testid="search-input"]').type('nonexistent product');
    cy.get('[data-testid="search-button"]').click();

    // Verify no results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('not.exist');

    // Verify no sort options are available
    cy.get('[data-testid="sort-relevance-btn"]').should('not.exist');
    cy.get('[data-testid="sort-price-btn"]').should('not.exist');
    cy.get('[data-testid="sort-date-btn"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
  });
});
